class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.0/commando_0.10.0_darwin_arm64.tar.gz"
      sha256 "b928a3e2efa860946460c96fee54a94ee4bcf6632ae10bebb18fcea8a99bdf14"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.0/commando_0.10.0_darwin_amd64.tar.gz"
      sha256 "8a5faff996e0be6438eab3a6276279b0c6fcb315922010fd67946a767dd0da51"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.0/commando_0.10.0_linux_arm64.tar.gz"
      sha256 "20c2c17f4bd1c2ac257503da4afb654cbd2844cabd13522cb974ef74d03dd8ae"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.10.0/commando_0.10.0_linux_amd64.tar.gz"
      sha256 "44e5f4c46340b8cd36a6380293b29eddd4752f92820fd9cbc642b87f3588f2fe"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
